import { dirname, join } from "node:path";

/** Absolute path of the official layerfs command inside a checkout. */
export function officialCli(layerfsRepo) {
  return join(layerfsRepo, "api", "cli", "src", "layerfs.js");
}

/** A PATH shim that runs the official command. It adds no calls of its own. */
export function shimSource(layerfsJs) {
  const target = JSON.stringify(layerfsJs);
  return `#!/usr/bin/env node
// Generated by layerfs-cursor-setup. Runs the official layerfs command.
import { spawn } from "node:child_process";

const child = spawn(process.execPath, [${target}, ...process.argv.slice(2)], { stdio: "inherit" });
child.on("error", (error) => {
  console.error(error.message);
  process.exit(1);
});
child.on("exit", (code, signal) => {
  if (signal) {
    process.kill(process.pid, signal);
    return;
  }
  process.exit(code ?? 1);
});
`;
}

export function shimPath(prefix) {
  return join(prefix, process.platform === "win32" ? "layerfs.js" : "layerfs");
}

export function cliDir(layerfsJs) {
  return dirname(layerfsJs);
}
